/* Plugins without dlopen.
 *
 * libnx cannot load libraries, so the core, the RSP HLE plugin and the null video plugin
 * are linked into the one program. A mupen64plus front end and the plugins find each
 * other's functions by name (osal_dynlib_getproc on a library handle); here a handle is a
 * pointer to a table of names and function pointers. The tables are generated by
 * builder/build-switch.sh from the symbols each library exports (gen/static_libs.c), after
 * it has given every plugin export a prefix, since all plugins export the same names
 * (PluginStartup, RomOpen, ...).
 *
 * This file replaces src/osal/dynamiclib_unix.c of the core and osal_dynamiclib_unix.c of
 * the RSP plugin. Those declare osal_dynlib_getproc with two different return types
 * (m64p_function and void*); both are a pointer in x0, so one definition serves both. */

#include <stddef.h>
#include <string.h>

#include "m64p_types.h"
#include "znx_switch.h"

struct znx_static_sym { const char* name; void (*function)(void); };
struct znx_static_lib { const char* name; const struct znx_static_sym* syms; };

extern const struct znx_static_lib* const znx_static_libs[]; /* gen/static_libs.c, NULL-terminated */

void* znx_static_lib(const char* name)
{
    for (int i = 0; znx_static_libs[i] != NULL; ++i) {
        if (strcmp(znx_static_libs[i]->name, name) == 0)
            return (void*)znx_static_libs[i];
    }
    return NULL;
}

void* osal_dynlib_getproc(void* lib, const char* name)
{
    const struct znx_static_lib* library = lib;
    if (library == NULL || name == NULL)
        return NULL;
    for (const struct znx_static_sym* s = library->syms; s->name != NULL; ++s) {
        if (strcmp(s->name, name) == 0)
            return (void*)s->function;
    }
    return NULL;
}

/* Only the RSP plugin calls these, for its optional fallback RSP: a path never names one
 * of the linked libraries, so there is nothing to open. */
m64p_error osal_dynlib_open(m64p_dynlib_handle* lib, const char* path)
{
    (void)path;
    if (lib != NULL)
        *lib = NULL;
    return M64ERR_INPUT_NOT_FOUND;
}

m64p_error osal_dynlib_close(m64p_dynlib_handle lib)
{
    (void)lib;
    return M64ERR_SUCCESS;
}
